			const mrt = new MultiRenderTarget(name, {
				width: textureSize.x,
				height: textureSize.y
			}, 1, this._scene, {
				types: [7],
				formats: [11],
				samplingModes: [1],
				generateDepthBuffer: false,
				generateDepthTexture: false,
				generateMipMaps: false
			}, [name]);
			mrt.clearColor = new Color4(0, 0, 0, 0);
			mrt.renderList = [];
			mrt.onClearObservable.add(() => {});
