					this._rotationsATexture.wrapU = 0;
					this._rotationsATexture.wrapV = 0;
					this._rotationsBTexture.wrapU = 0;
					this._rotationsBTexture.wrapV = 0;
					this._rotationScaleTexture.wrapU = 0;
					this._rotationScaleTexture.wrapV = 0;
